ALTER TABLE match_lineups ADD COLUMN pitch_x numeric NOT NULL DEFAULT 50 CHECK(pitch_x BETWEEN 0 AND 100), ADD COLUMN pitch_y numeric NOT NULL DEFAULT 50 CHECK(pitch_y BETWEEN 0 AND 100), ADD COLUMN shirt_number integer CHECK(shirt_number BETWEEN 1 AND 99);
CREATE TABLE match_lineup_settings(match_id uuid PRIMARY KEY REFERENCES matches, starter_limit integer NOT NULL DEFAULT 7 CHECK(starter_limit IN (5,7,9,11)), home_name varchar(80) NOT NULL DEFAULT 'Home squad', away_name varchar(80) NOT NULL DEFAULT 'Away squad', home_color varchar(7) NOT NULL DEFAULT '#801735', away_color varchar(7) NOT NULL DEFAULT '#475463');
